<?php require __DIR__ . '/../partials/header.php'; ?>
<div class="card"><div class="card-header"><h1>Your Cart</h1><p>Review your items before checkout.</p></div><?php if($generalErr):?><div class="alert alert-error"><?php echo e($generalErr);?></div><?php endif;?>
<?php if(empty($_SESSION['cart'])):?><p class="muted">Cart is empty. <a href="<?php echo e(url_for('customer','browse'));?>">Browse products</a></p><?php else:?><table class="data-table"><tr><th>#</th><th>Product</th><th>Price</th><th>Qty</th><th>Subtotal</th><th>Action</th></tr><?php foreach($_SESSION['cart'] as $i=>$it):$sub=(float)$it['price']*(int)$it['qty'];?><tr><td><?php echo e($i+1);?></td><td><?php echo e($it['name']);?></td><td>TK <?php echo e(number_format((float)$it['price'],2));?></td><td><form method="post" class="inline-form" action="<?php echo e(url_for('customer','cart'));?>"><?php echo csrf_field();?><input type="hidden" name="action" value="update"><input type="hidden" name="idx" value="<?php echo e($i);?>"><input type="number" name="qty" value="<?php echo e($it['qty']);?>" min="1" style="width:60px;padding:6px;"><button class="btn btn-secondary btn-small">Update</button></form></td><td>TK <?php echo e(number_format($sub,2));?></td><td><form method="post" action="<?php echo e(url_for('customer','cart'));?>"><?php echo csrf_field();?><input type="hidden" name="action" value="remove"><input type="hidden" name="idx" value="<?php echo e($i);?>"><button class="btn btn-secondary btn-small">Remove</button></form></td></tr><?php endforeach;?><tr><th colspan="4" style="text-align:right;">Total</th><th>TK <?php echo e(number_format($total,2));?></th><th></th></tr></table><p class="mt"><a class="btn btn-secondary" href="<?php echo e(url_for('customer','browse'));?>">Continue Shopping</a> <a class="btn btn-primary" href="<?php echo e(url_for('customer','checkout'));?>">Checkout</a></p><form method="post" action="<?php echo e(url_for('customer','cart'));?>"><?php echo csrf_field();?><input type="hidden" name="action" value="clear"><button class="btn btn-secondary btn-small" data-confirm="Clear cart?">Clear Cart</button></form><?php endif;?></div>
<?php require __DIR__ . '/../partials/footer.php'; ?>
